class V1PresentationDependencies(
 val getStore:GetStore,val connectStore:ConnectStore,val disconnectStore:DisconnectStore,val getOrders:GetOrders,val getOrder:GetOrder,val updateOrder:UpdateOrder,val addOrderNote:AddOrderNote,
 val getProducts:GetProducts,val getProduct:GetProduct,val createProduct:CreateProduct,val updateProduct:UpdateProduct,val deleteProduct:DeleteProduct,
 val getVariations:GetVariations,val getVariation:GetVariation,val createVariation:CreateVariation,val updateVariation:UpdateVariation,val deleteVariation:DeleteVariation,
 val getAttributes:GetAttributes,val getAttribute:GetAttribute,val createAttribute:CreateAttribute,val updateAttribute:UpdateAttribute,val deleteAttribute:DeleteAttribute,
 val getTerms:GetTerms,val getTerm:GetTerm,val createTerm:CreateTerm,val updateTerm:UpdateTerm,val deleteTerm:DeleteTerm,val getConnectionState:GetConnectionState,val getSyncState:GetSyncState,val getPending:GetPendingOperations,
 val getConflicts:suspend(StoreId)->CoreResult<List<Conflict>>,val resolveConflict:suspend(StoreId,EntityId,ConflictResolution)->CoreResult<Unit>,val syncPending:SyncPendingOperations,val initialStoreId:String?,val onStoreConnected:(String)->Unit,val onStoreDisconnected:()->Unit)

sealed interface FeatureUiState<out T>{data object Loading:FeatureUiState<Nothing>;data object Empty:FeatureUiState<Nothing>;data class Success<T>(val value:T):FeatureUiState<T>;data class Error(val message:String):FeatureUiState<Nothing>}
private fun <T:ViewModel> vmFactory(create:()->T)=object:ViewModelProvider.Factory{override fun <M:ViewModel>create(modelClass:Class<M>):M=create() as M}
private fun storeIdFor(url:String)=StoreId("store-${url.trim().trimEnd('/').lowercase().hashCode().toUInt().toString(16)}")

class ConnectionViewModel(private val d:V1PresentationDependencies):ViewModel(){private val _state=MutableStateFlow<FeatureUiState<StoreConnection>>(FeatureUiState.Loading);val state:StateFlow<FeatureUiState<StoreConnection>>=_state.asStateFlow();fun connect(url:String,key:String,secret:String){viewModelScope.launch{_state.value=FeatureUiState.Loading;when(val r=d.connectStore(StoreConnection(storeIdFor(url),url.trim().trimEnd('/'),ConnectionState.DISCONNECTED,null),key,secret)){is CoreResult.Success->{_state.value=FeatureUiState.Success(r.value);d.onStoreConnected(r.value.storeId.value)};is CoreResult.Failure->_state.value=FeatureUiState.Error(r.error.toString())}}}}
class OrdersViewModel(private val d:V1PresentationDependencies):ViewModel(){private val _state=MutableStateFlow<FeatureUiState<List<Order>>>(FeatureUiState.Loading);val state=_state.asStateFlow();fun load(s:StoreId,page:Int=1,search:String?=null){viewModelScope.launch{_state.value=FeatureUiState.Loading;_state.value=when(val r=d.getOrders(s,page,30,search)){is CoreResult.Success->if(r.value.isEmpty())FeatureUiState.Empty else FeatureUiState.Success(r.value);is CoreResult.Failure->FeatureUiState.Error(r.error.toString())}}}}
class OrderDetailViewModel(private val d:V1PresentationDependencies):ViewModel(){private val _state=MutableStateFlow<FeatureUiState<Order>>(FeatureUiState.Loading);val state=_state.asStateFlow();fun load(s:StoreId,id:EntityId){viewModelScope.launch{_state.value=when(val r=d.getOrder(s,id)){is CoreResult.Success->FeatureUiState.Success(r.value);is CoreResult.Failure->FeatureUiState.Error(r.error.toString())}}};fun update(s:StoreId,o:Order){viewModelScope.launch{_state.value=when(val r=d.updateOrder(s,o.id,o)){is CoreResult.Success->FeatureUiState.Success(r.value);is CoreResult.Failure->FeatureUiState.Error(r.error.toString())}}};fun note(s:StoreId,id:EntityId,text:String){viewModelScope.launch{d.addOrderNote(s,id,text)}}}
class ProductsViewModel(private val d:V1PresentationDependencies):ViewModel(){private val _state=MutableStateFlow<FeatureUiState<List<Product>>>(FeatureUiState.Loading);val state=_state.asStateFlow();fun load(s:StoreId,page:Int=1,search:String?=null){viewModelScope.launch{_state.value=FeatureUiState.Loading;_state.value=when(val r=d.getProducts(s,page,30,search)){is CoreResult.Success->if(r.value.isEmpty())FeatureUiState.Empty else FeatureUiState.Success(r.value);is CoreResult.Failure->FeatureUiState.Error(r.error.toString())}}}}
